script:
event = {
	id = fircon.10
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		has_first_contact_dlc = yes
		OR = {
			any_playable_country = {
				has_country_flag = built_observation_post
			}
			any_playable_country = {
				is_nomadic = yes
				any_owned_nonprimary_starbase = {
					is_waystation_starbase = yes
				}
			}
		}
	}

	immediate = {
		every_playable_country = {
			limit = {
				has_country_flag = built_observation_post
				NOR = {
					has_country_flag = society_insights
					has_country_flag = engineering_insights
					has_country_flag = physics_insights
					has_country_flag = pending_insight_tech
				}
			}
			clear_variable = observation_post_insight
			if = {
				limit = {
					NOT = { is_variable_set = observation_insight_change_comparator }
				}
				set_variable = {
					which = observation_insight_change_comparator
					value = 0
				}
			}
			if = {
				limit = {
					NOT = { is_variable_set = observation_post_insight }
				}
				set_variable = {
					which = observation_post_insight
					value = 0
				}
			}
			if = {
				limit = {
					NOT = { is_variable_set = observation_insight_change }
				}
				set_variable = {
					which = observation_insight_change
					value = 0
				}
			}
			every_pre_ftl_within_border = {
				limit = {
					capital_scope = { has_observation_outpost = yes }
					has_awareness < 100
					NOT = { has_country_flag = solarpunk_country }
				}
				if = {
					limit = {
						capital_scope = {
							observation_outpost = {
								has_mission = passive_observation
							}
						}
					}
					prev = {
						change_variable = {
							which = observation_post_insight
							value = 0.5
						}
					}
				}
				else = {
					prev = {
						change_variable = {
							which = observation_post_insight
							value = 1
						}
					}
				}
			}
			if = {
				limit = {
					check_variable = {
						which = observation_post_insight
						value > 0
					}
				}
				if = {
					limit = {
						count_situation = {
							limit = {
								is_situation_type = situation_observation_insight
							}
							count = 0
						}
					}
					start_situation = {
						type = situation_observation_insight
						target = this
						effect = {
							owner = {
								switch = {
									trigger = has_country_flag
									favored_insights = {
										prev = { set_situation_approach = approach_favor_insights }
									}
									favored_mission = {
										prev = { set_situation_approach = approach_favor_mission }
									}
									default = {
										prev = { set_situation_approach = approach_study_insights }
									}
								}
							}
						}
					}
				}
			}
		}
		every_playable_country = {
			limit = {
				is_nomadic = yes
				NOR = {
					has_country_flag = society_insights
					has_country_flag = engineering_insights
					has_country_flag = physics_insights
					has_country_flag = pending_insight_tech
				}
				any_owned_nonprimary_starbase = {
					is_waystation_starbase = yes
				}
			}
			set_variable = { which = observation_post_insight value = 0 }
			save_event_target_as = nomad_pre_ftl_observer
			every_owned_nonprimary_starbase = {
				limit = { is_waystation_starbase = yes }
				solar_system = {
					every_system_planet = {
						limit = {
							has_observation_outpost = no
							exists = owner
							owner = {
								is_primitive = yes
								has_awareness < 100
								NOT = { has_country_flag = solarpunk_country }
							}
						}
						event_target:nomad_pre_ftl_observer = {
							change_variable = {
								which = observation_post_insight
								value = 0.5
							}
						}
					}
				}
			}
			if = {
				limit = {
					check_variable = {
						which = observation_post_insight
						value > 0
					}
				}
				if = {
					limit = {
						count_situation = {
							limit = { is_situation_type = situation_observation_insight }
							count = 0
						}
					}
					start_situation = {
						type = situation_observation_insight
						target = this
						effect = {
							owner = {
								prev = { set_situation_approach = approach_study_insights }
							}
						}
					}
				}
			}
		}
		# Consume pending_insight_tech for Nomads when no observation events remain to do so.
		# Non-Nomad observation events set an insight type flag before calling add_observation_insight_effect,
		# but Nomads have fewer routed events and can exhaust them before the situation completes.
		every_playable_country = {
			limit = {
				is_nomadic = yes
				has_country_flag = pending_insight_tech
				NOR = {
					has_country_flag = society_insights
					has_country_flag = engineering_insights
					has_country_flag = physics_insights
				}
				any_owned_nonprimary_starbase = {
					is_waystation_starbase = yes
				}
			}
			# Set a random insight category flag (needed for add_observation_insight_effect to grant the correct tech).
			if = {
				limit = {
					has_all_physics_insights = no
				}
				set_country_flag = physics_insights
			}
			else_if = {
				limit = {
					has_all_society_insights = no
				}
				set_country_flag = society_insights
			}
			else_if = {
				limit = {
					has_all_engineering_insights = no
				}
				set_country_flag = engineering_insights
			}
			random_owned_nonprimary_starbase = {
				limit = {
					is_waystation_starbase = yes
				}
				save_event_target_as = nomad_outpost_placeholder
			}
			add_observation_insight_effect = {
				VALUE = 0
				OUTPOST = event_target:nomad_outpost_placeholder
			}
		}
	}
}

