	}

	immediate = {
		every_playable_country = {
			limit = {
				NOT = { is_same_value = root.owner }
				intel_level = {
					system = from
					level > low
				}
			}
			country_event = { id = fircon.3510 }
		}
		if = {
			limit = {
				FROM.owner = {
					OR = {
						is_country_type = default
						is_country_type = awakened_fallen_empire
					}
				}
			}
			root.owner = {
				declare_war = {
					target = FROM.owner
					attacker_war_goal = wg_cleansing
				}
			}
		}
	}
}

