				from.solar_system = {
					spawn_system = {
						min_distance = 5
						max_distance = 8
						max_jumps = 0
						initializer = "solarpunk_02"
					}
					set_star_flag = solarpunk_system_revealed
					last_created_system = {
						random_system_planet = {
							limit = {
								has_carrier_flag = solarpunk_capital
							}
							if = {
								limit = {
									NOT = {
										any_galaxy_species = {
											species_portrait = mol7
										}
