								}
								create_species = {
									name = "NAME_Habinte"
									plural = "NAME_Habinte_plural"
									adjective = "NAME_Habinte_adj"
									class = MOL
									portrait = mol7
									traits = random
									homeworld = this
								}
							}
							else_if = {
								limit = {
									NOT = {
										any_galaxy_species = {
											species_portrait = fun3
										}
									}
								}
								create_species = {
									name = "NAME_Habinte"
									plural = "NAME_Habinte_plural"
									adjective = "NAME_Habinte_adj"
									class = FUN
									portrait = fun3
									traits = random
									homeworld = this
								}
							}
							else = {
